    Bug 1935800 - Remove status message when messages are deleted on POP3 server. r=mkmelin

    When messages in a local inbox are deleted by the user, the actual deletion is performed the next time the POP3 server is contacted to get new messages. This removes the confusing status message about message being "received" in this case.

    Differential Revision: https://phabricator.services.mozilla.com/D232335

diff --git a/mailnews/local/src/Pop3Client.sys.mjs b/mailnews/local/src/Pop3Client.sys.mjs
index 33990248c22..4c68f1eca23 100644
--- a/mailnews/local/src/Pop3Client.sys.mjs
+++ b/mailnews/local/src/Pop3Client.sys.mjs
@@ -1233,9 +1233,10 @@ export class Pop3Client {
         const uidlState = this._uidlMap.get(uidl);
         if (uidlState) {
           if (
-            uidlState.status == UIDL_KEEP &&
-            (!this._server.leaveMessagesOnServer ||
-              uidlState.receivedAt < this._cutOffTimestamp)
+            (uidlState.status == UIDL_KEEP &&
+              (!this._server.leaveMessagesOnServer ||
+                uidlState.receivedAt < this._cutOffTimestamp)) ||
+            uidlState.status == UIDL_DELETE
           ) {
             // Delete this message.
             this._messagesToHandle.push({
@@ -1243,15 +1244,13 @@ export class Pop3Client {
               messageNumber,
               status: UIDL_DELETE,
             });
-          } else if (
-            [UIDL_FETCH_BODY, UIDL_DELETE].includes(uidlState.status)
-          ) {
+          } else if (uidlState.status == UIDL_FETCH_BODY) {
             // Fetch the full message.
             this._newMessageTotal++;
             this._messagesToHandle.push({
               ...uidlState,
               messageNumber,
-              status: uidlState.status,
+              status: UIDL_FETCH_BODY,
             });
           } else {
             // Do nothing to this message.
